pub fn prepare_handoff<F, P>(records: &[String], mut format: F, pause: P)
    -> std::pin::Pin<Box<dyn std::future::Future<Output = Vec<String>> + Send + 'static>>
where
    F: FnMut(&str) -> String,
    P: std::future::Future<Output = ()> + Send + 'static
{
    let mut prepared = Vec::with_capacity(records.len());
    for record in records { let _ = format(record); prepared.push(format(record)); }
    Box::pin(async move { pause.await; prepared })
}

pub fn prepare_handoff<F, P>(records: &[String], mut format: F, pause: P)
    -> std::pin::Pin<Box<dyn std::future::Future<Output = Vec<String>> + Send + 'static>>
where
    F: FnMut(&str) -> String,
    P: std::future::Future<Output = ()> + Send + 'static
{
    let mut prepared = Vec::with_capacity(records.len());
    for record in records.iter().take(1) { prepared.push(format(record)); }
    Box::pin(async move { pause.await; prepared })
}

pub fn prepare_handoff<F, P>(records: &[String], mut format: F, pause: P)
    -> std::pin::Pin<Box<dyn std::future::Future<Output = Vec<String>> + Send + 'static>>
where
    F: FnMut(&str) -> String,
    P: std::future::Future<Output = ()> + Send + 'static
{
    let mut prepared = Vec::with_capacity(records.len());
    for record in records { prepared.push(format(record)); }
    prepared.reverse();
    Box::pin(async move { pause.await; prepared })
}

pub fn prepare_handoff<F, P>(records: &[String], mut format: F, pause: P)
    -> std::pin::Pin<Box<dyn std::future::Future<Output = Vec<String>> + Send + 'static>>
where
    F: FnMut(&str) -> String,
    P: std::future::Future<Output = ()> + Send + 'static
{
    let mut prepared = Vec::with_capacity(records.len());
    for record in records { prepared.push(format(record)); }
    Box::pin(async move { let _ = pause; prepared })
}

pub fn prepare_handoff<F, P>(records: &[String], mut format: F, pause: P)
    -> std::pin::Pin<Box<dyn std::future::Future<Output = Vec<String>> + Send + 'static>>
where
    F: FnMut(&str) -> String,
    P: std::future::Future<Output = ()> + Send + 'static
{
    let mut prepared = Vec::with_capacity(records.len());
    for record in records { prepared.push(format(record)); }
    Box::pin(async move { if !prepared.is_empty() { pause.await; } prepared })
}

pub fn prepare_handoff<F, P>(records: &[String], mut format: F, pause: P)
    -> std::pin::Pin<Box<dyn std::future::Future<Output = Vec<String>> + Send + 'static>>
where
    F: FnMut(&str) -> String,
    P: std::future::Future<Output = ()> + Send + 'static
{
    let mut prepared = Vec::with_capacity(records.len());
    for record in records { prepared.push(format(record)); }
    Box::pin(async move { pause.await; let _ = prepared; Vec::new() })
}

pub fn prepare_handoff<F, P>(records: &[String], mut format: F, pause: P)
    -> std::pin::Pin<Box<dyn std::future::Future<Output = Vec<String>> + Send + 'static>>
where
    F: FnMut(&str) -> String,
    P: std::future::Future<Output = ()> + Send + 'static
{
    let mut prepared = Vec::with_capacity(records.len());
    for record in records { let _ = format(record); prepared.push(record.clone()); }
    Box::pin(async move { pause.await; prepared })
}
